INSERT INTO public.exercises (id,name,category,equipment,primary_muscle,secondary_muscles,aliases,movement_pattern,force_type,difficulty,is_bodyweight,is_unilateral,tracking_type,default_unit,instructions,tips,is_active) VALUES
  ('7665f3c7-a2d4-4456-a9fa-000ce24e3ed8', 'Front Squat', 'Squat', 'Barbell', 'Quads', ARRAY['Glutes','Core']::text[], ARRAY['barbell front squat','bb front squat','front barbell squat']::text[], 'squat', 'push', 'intermediate', false, false, 'weight_reps', 'lb', 'Rest the bar across the front of your shoulders with your elbows high, then squat down until your thighs are at least parallel and drive back up.', 'Keep your elbows up and torso tall the whole time — if your elbows drop, the bar rolls forward.', true),
  ('5632af50-2230-4d80-8c14-8ac56761a7ce', 'Smith Machine Squat', 'Squat', 'Smith', 'Quads', ARRAY['Glutes']::text[], ARRAY['smith squat','smith machine back squat','smith machine squats']::text[], 'squat', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'With the bar on your upper back on the Smith machine, squat down to at least parallel and press back up along the fixed path.', 'Set your feet slightly forward of the bar so your knees track well on the guided rails.', true),
  ('69ca08c3-143c-49f3-b2c9-925d6d294c09', 'Hack Squat', 'Squat', 'Machine', 'Quads', ARRAY['Glutes']::text[], ARRAY['machine hack squat','hack squat machine','hack squats']::text[], 'squat', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Position your shoulders and back against the pads, then squat down to at least parallel and press through your whole foot to stand.', 'Keep your lower back flat against the pad — don''t let your hips round off the seat at the bottom.', true),
  ('889e224a-c534-48b4-a5f8-55d8bada6af3', 'Dumbbell Squat', 'Squat', 'Dumbbell', 'Quads', ARRAY['Glutes']::text[], ARRAY['db squat','dumbbell squats']::text[], 'squat', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Hold a dumbbell in each hand at your sides, squat down until your thighs are at least parallel, then stand back up.', 'Let the dumbbells travel down beside your legs and keep your chest up out of the bottom.', true),
  ('97501496-7f81-4552-82ab-d3f326b8ff06', 'Bodyweight Squat', 'Squat', 'Bodyweight', 'Quads', ARRAY['Glutes']::text[], ARRAY['air squat','bw squat','bodyweight squats']::text[], 'squat', 'push', 'beginner', true, false, 'bodyweight_reps', 'lb', 'With no added weight, squat down until your thighs are at least parallel, then stand tall.', 'Push your knees out and reach your arms forward for balance as you descend.', true),
  ('ebfb4a3a-28b9-4093-bcb2-d14b1d61aa88', 'Walking Lunge', 'Squat', 'Dumbbell', 'Quads', ARRAY['Glutes']::text[], ARRAY['walking lunges','db walking lunge','dumbbell walking lunge']::text[], 'lunge', 'push', 'intermediate', false, true, 'weight_reps', 'lb', 'Step forward into a lunge until both knees are about 90 degrees, then push off the front foot and step straight into the next lunge.', 'Take a long enough step that your front knee stays over your foot, not way past your toes.', true),
  ('a3ffb069-e0ea-4d01-a038-f9f72b1dd7fe', 'Forward Lunge', 'Squat', 'Bodyweight', 'Quads', ARRAY['Glutes']::text[], ARRAY['forward lunges','front lunge','front lunges']::text[], 'lunge', 'push', 'beginner', true, true, 'bodyweight_reps', 'lb', 'Step forward into a lunge until both knees are about 90 degrees, then push back to standing on the same leg.', 'Keep your torso upright and control the descent — don''t let your back knee crash down.', true),
  ('eee8a605-10d6-41ad-9b79-65d626b598db', 'Lateral Lunge', 'Squat', 'Bodyweight', 'Quads', ARRAY['Glutes','Adductors']::text[], ARRAY['side lunge','lateral lunges','side lunges']::text[], 'lunge', 'push', 'beginner', true, true, 'bodyweight_reps', 'lb', 'Step out wide to one side and sit back into that hip while the other leg stays straight, then push back to center.', 'Sit back into the bent hip like a one-legged squat and keep both feet flat.', true),
  ('8a56a474-29e1-47b1-a68f-8cb98718223e', 'Pistol Squat', 'Squat', 'Bodyweight', 'Quads', ARRAY['Glutes','Core']::text[], ARRAY['single leg squat','pistol squats','one leg squat']::text[], 'squat', 'push', 'advanced', true, true, 'bodyweight_reps', 'lb', 'Standing on one leg with the other extended in front, squat all the way down and drive back up on the single leg.', 'Reach your arms forward as a counterbalance and keep the working heel planted.', true),
  ('7948f9c4-2ec1-432b-ad79-7f27c5961577', 'Wall Sit', 'Squat', 'Bodyweight', 'Quads', ARRAY['Glutes']::text[], ARRAY['wall squat','wall sits','wall hold']::text[], 'squat', 'static', 'beginner', true, false, 'time', 'sec', 'Slide your back down a wall until your thighs are parallel to the floor and hold that seated position.', 'Keep your knees over your ankles at 90 degrees and breathe steadily through the hold.', true),
  ('93bedb5c-8df3-4e82-bfa7-f0a4bfed3499', 'Sumo Deadlift', 'Hinge', 'Barbell', 'Hamstrings', ARRAY['Glutes','Quads','Back']::text[], ARRAY['sumo dl','sumo deadlifts','wide stance deadlift']::text[], 'hinge', 'pull', 'advanced', false, false, 'weight_reps', 'lb', 'With a wide stance and hands inside your knees, grip the bar, brace, and drive through the floor to stand it up.', 'Push your knees out and drop your hips so your shoulders stay over the bar at the start.', true),
  ('1254ff9a-3bee-4fc1-b7db-819d6a359866', 'Stiff-Leg Deadlift', 'Hinge', 'Barbell', 'Hamstrings', ARRAY['Glutes','Back']::text[], ARRAY['stiff leg deadlift','straight leg deadlift','stiff legged deadlift']::text[], 'hinge', 'pull', 'intermediate', false, false, 'weight_reps', 'lb', 'With nearly straight legs, hinge at your hips to lower the bar down your legs until you feel a hamstring stretch, then stand back up.', 'Keep the bar close and your back flat — stop lowering when your back wants to round.', true),
  ('6107df4c-5295-4268-9dc5-46e922ca9db9', 'Dumbbell Romanian Deadlift', 'Hinge', 'Dumbbell', 'Hamstrings', ARRAY['Glutes']::text[], ARRAY['db rdl','dumbbell rdl','db romanian deadlift']::text[], 'hinge', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'Hold a dumbbell in each hand at your thighs, soften your knees, and push your hips back to lower the weights until you feel a hamstring stretch.', 'Let the dumbbells graze the front of your legs and drive your hips forward to finish.', true),
  ('38afdd22-387a-4b76-a895-e815ea24f28c', 'Single-Leg Romanian Deadlift', 'Hinge', 'Dumbbell', 'Hamstrings', ARRAY['Glutes','Core']::text[], ARRAY['single leg rdl','single leg deadlift','b stance rdl','one leg rdl']::text[], 'hinge', 'pull', 'intermediate', false, true, 'weight_reps', 'lb', 'Balancing on one leg, hinge forward and reach the dumbbell toward the floor as your free leg extends behind you, then return to standing.', 'Keep your hips level and square to the floor — don''t let the back hip open up.', true),
  ('967e443d-f423-496b-a125-ee51406b1529', 'Good Morning', 'Hinge', 'Barbell', 'Hamstrings', ARRAY['Glutes','Back']::text[], ARRAY['barbell good morning','good mornings']::text[], 'hinge', 'pull', 'intermediate', false, false, 'weight_reps', 'lb', 'With the bar on your upper back, soften your knees and hinge your torso forward until you feel a hamstring stretch, then stand back up.', 'Push your hips back rather than just bending over, and keep a flat back throughout.', true),
  ('b0c178b6-bd81-477d-ae23-2a9aa40d67b4', 'Back Extension', 'Hinge', 'Bodyweight', 'Hamstrings', ARRAY['Glutes','Back']::text[], ARRAY['hyperextension','hyper extension','back extensions','45 degree back extension']::text[], 'hinge', 'pull', 'beginner', true, false, 'bodyweight_reps', 'lb', 'Anchor your legs on the bench and hinge at your hips to lower your torso, then squeeze your glutes and hamstrings to raise back to a straight line.', 'Stop at a straight body line at the top — don''t hyperextend or crank your lower back.', true),
  ('1d49b4cb-7006-4a4b-99ed-390d0f7c2072', 'Kettlebell Swing', 'Hinge', 'Kettlebell', 'Glutes', ARRAY['Hamstrings','Core']::text[], ARRAY['kb swing','kettlebell swings','russian swing']::text[], 'hinge', 'pull', 'intermediate', false, false, 'weight_reps', 'lb', 'Hike the kettlebell back between your legs, then snap your hips forward to float it up to about chest height and let it swing back down.', 'Power comes from a hip snap, not your arms or a squat — the bell floats because your hips drive it.', true),
  ('ff15ede3-a361-415a-8e20-6a7244bad0b3', 'Glute Bridge', 'Hinge', 'Bodyweight', 'Glutes', ARRAY['Hamstrings']::text[], ARRAY['floor glute bridge','glute bridges','hip bridge']::text[], 'hinge', 'push', 'beginner', true, false, 'bodyweight_reps', 'lb', 'Lying on your back with knees bent and feet flat, drive through your heels to lift your hips until your body is straight from knees to shoulders.', 'Squeeze your glutes hard at the top and avoid arching your lower back to get higher.', true),
  ('da2d9535-6e82-4790-84c9-8e1a0d549718', 'Single-Leg Glute Bridge', 'Hinge', 'Bodyweight', 'Glutes', ARRAY['Hamstrings','Core']::text[], ARRAY['single leg glute bridge','one leg glute bridge','single leg hip bridge']::text[], 'hinge', 'push', 'beginner', true, true, 'bodyweight_reps', 'lb', 'From a glute bridge setup, extend one leg and drive through the planted heel to raise your hips, then lower under control.', 'Keep your hips level — don''t let the side of the raised leg drop as you lift.', true),
  ('7ef7b658-31d6-45cc-8208-aa44e77acedd', 'Machine Hip Thrust', 'Hinge', 'Machine', 'Glutes', ARRAY['Hamstrings']::text[], ARRAY['glute drive','hip thrust machine','machine glute thrust']::text[], 'hinge', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Set your back against the pad, place the belt or pad across your hips, and drive your hips up until your thighs are level, then lower under control.', 'Finish with a hard glute squeeze and keep your chin tucked so your ribs stay down.', true),
  ('9e3f944f-fee5-45bc-bd5c-c28dafeb676f', 'Smith Machine Hip Thrust', 'Hinge', 'Smith', 'Glutes', ARRAY['Hamstrings']::text[], ARRAY['smith hip thrust','smith machine hip thrusts']::text[], 'hinge', 'push', 'intermediate', false, false, 'weight_reps', 'lb', 'With your upper back on a bench and the Smith bar across your hips, drive your hips up until your thighs are level, then lower under control.', 'Pad the bar over your hips and press it straight up the rails with a strong glute squeeze at the top.', true),
  ('074c569f-6f2c-4ced-a46d-8c90a683cf94', 'Hip Adduction', 'Hinge', 'Machine', 'Adductors', ARRAY['Glutes']::text[], ARRAY['adductor machine','inner thigh machine','hip adductor','seated hip adduction']::text[], 'isolation', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Sit in the machine with your legs against the outer pads and squeeze your knees together against the resistance, then return slowly.', 'Control the return so your inner thighs do the work the whole way out.', true),
  ('2b30eeef-8550-44ea-8190-67bdeab5c724', 'Seated Leg Curl', 'Hinge', 'Machine', 'Hamstrings', '{}'::text[], ARRAY['seated hamstring curl','seated leg curls']::text[], 'isolation', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'Sit with the pad on the back of your lower legs and curl your heels down and under the seat, then return slowly.', 'Keep your thighs pinned under the pad and control the weight back up.', true),
  ('c0d5c180-10ea-420f-8c55-fb07cfe5a7d2', 'Lying Leg Curl', 'Hinge', 'Machine', 'Hamstrings', '{}'::text[], ARRAY['prone leg curl','lying leg curls','lying hamstring curl']::text[], 'isolation', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'Lying face-down with the pad on the back of your ankles, curl your heels toward your glutes, then lower slowly.', 'Keep your hips down on the pad — don''t let them pop up to swing the weight.', true),
  ('3d8d2c2b-8770-4c5b-8b8d-fa467c5da0d4', 'Machine Chest Press', 'Horizontal Push', 'Machine', 'Chest', ARRAY['Triceps','Shoulders']::text[], ARRAY['chest press','seated chest press','machine bench press','chest press machine']::text[], 'horizontal_push', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Sit with the handles at chest height and press them straight forward until your arms are extended, then return under control.', 'Set the seat so the handles line up with mid-chest and keep your shoulder blades back on the pad.', true),
  ('b7f0edb8-f473-45da-8488-8a325265b26f', 'Smith Machine Bench Press', 'Horizontal Push', 'Smith', 'Chest', ARRAY['Triceps']::text[], ARRAY['smith bench','smith machine chest press','smith bench press']::text[], 'horizontal_push', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Lying on a bench under the Smith bar, unrack and lower the bar to your chest, then press it back up along the fixed path.', 'Position the bench so the bar path meets your mid-chest at the bottom.', true),
  ('9e91fb9f-c790-4890-abad-0a2e4cc13374', 'Decline Bench Press', 'Horizontal Push', 'Barbell', 'Chest', ARRAY['Triceps']::text[], ARRAY['decline barbell bench press','decline barbell bench','decline press']::text[], 'horizontal_push', 'push', 'intermediate', false, false, 'weight_reps', 'lb', 'On a decline bench, lower the bar to your lower chest, then press it back up until your arms are extended.', 'Keep your feet hooked and shoulder blades pinned so the bar path stays over your lower chest.', true),
  ('d4b9f7e6-06f3-4caf-aaee-977061ee9258', 'Dumbbell Fly', 'Horizontal Push', 'Dumbbell', 'Chest', '{}'::text[], ARRAY['db fly','chest fly','dumbbell flye','dumbbell flyes']::text[], 'isolation', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Lying on a flat bench with dumbbells above your chest, open your arms in a wide arc with a slight elbow bend, then bring them back together over your chest.', 'Keep a soft, fixed elbow bend the whole rep and feel the stretch across your chest, not your shoulders.', true),
  ('2fc0c511-e456-4275-8cf8-15ebda4a7028', 'Pec Deck', 'Horizontal Push', 'Machine', 'Chest', '{}'::text[], ARRAY['pec deck fly','machine fly','pec fly machine','chest fly machine']::text[], 'isolation', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Sit with your forearms or hands on the pads and squeeze them together in front of your chest, then return under control.', 'Lead with your elbows and squeeze your chest — don''t just push with your hands.', true),
  ('c6b852dd-8773-4417-9244-b51989a308b1', 'Incline Push-Up', 'Horizontal Push', 'Bodyweight', 'Chest', ARRAY['Triceps']::text[], ARRAY['incline pushup','incline push ups','hands elevated push up']::text[], 'horizontal_push', 'push', 'beginner', true, false, 'bodyweight_reps', 'lb', 'With your hands elevated on a bench or bar, lower your chest to the surface and press back up in a straight line.', 'The higher the hands, the easier it is — keep your body straight from head to heels.', true),
  ('a1bb3980-ae49-48ce-a0b5-91bffd5daeda', 'Knee Push-Up', 'Horizontal Push', 'Bodyweight', 'Chest', ARRAY['Triceps']::text[], ARRAY['knee pushup','modified push up','push up on knees']::text[], 'horizontal_push', 'push', 'beginner', true, false, 'bodyweight_reps', 'lb', 'From your knees with hands under your shoulders, lower your chest toward the floor and press back up.', 'Keep a straight line from your knees to your head — don''t let your hips sag or pike up.', true),
  ('eecf2677-57d4-4bc1-a0e9-bd3ffe59ab15', 'Decline Push-Up', 'Horizontal Push', 'Bodyweight', 'Chest', ARRAY['Triceps','Shoulders']::text[], ARRAY['decline pushup','feet elevated push up','decline push ups']::text[], 'horizontal_push', 'push', 'intermediate', true, false, 'bodyweight_reps', 'lb', 'With your feet elevated on a bench, lower your chest to the floor and press back up in a straight line.', 'Elevating the feet shifts load to your upper chest and shoulders — keep your core tight so your hips don''t sag.', true),
  ('2205e63b-3486-4d1b-bc9d-189ee9d4b3bd', 'Close-Grip Bench Press', 'Horizontal Push', 'Barbell', 'Triceps', ARRAY['Chest']::text[], ARRAY['cgbp','close grip bench','close grip bench press']::text[], 'horizontal_push', 'push', 'intermediate', false, false, 'weight_reps', 'lb', 'With a shoulder-width grip, lower the bar to your lower chest keeping your elbows close, then press back up.', 'Tuck your elbows toward your sides so the triceps take the load rather than flaring wide.', true),
  ('ced6dc23-e063-4dad-a460-1e3f7b034613', 'Single-Arm Cable Row', 'Horizontal Pull', 'Cable', 'Back', ARRAY['Biceps']::text[], ARRAY['one arm cable row','single arm seated cable row','single arm cable rows']::text[], 'horizontal_pull', 'pull', 'beginner', false, true, 'weight_reps', 'lb', 'Sitting or in a staggered stance at a low pulley, pull the handle to your side with one arm while keeping your torso stable, then extend under control.', 'Let your shoulder blade travel with the weight and resist twisting your torso to cheat the row.', true),
  ('89ccfccf-3e25-4c79-9417-c4086d5f0921', 'Chest-Supported Row', 'Horizontal Pull', 'Machine', 'Back', ARRAY['Biceps']::text[], ARRAY['chest supported machine row','chest supported row','seal row machine']::text[], 'horizontal_pull', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'With your chest against the pad, pull the handles toward you by driving your elbows back, then return under control.', 'Keep your chest glued to the pad so your back does the work instead of body english.', true),
  ('1b45741b-4326-4158-ac56-ede5744d3e54', 'Chest-Supported Dumbbell Row', 'Horizontal Pull', 'Dumbbell', 'Back', ARRAY['Biceps']::text[], ARRAY['incline dumbbell row','chest supported db row','chest supported dumbbell row']::text[], 'horizontal_pull', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'Lying face-down on an incline bench, row the dumbbells up by driving your elbows back, then lower under control.', 'The bench takes momentum out of it — squeeze your shoulder blades at the top of each rep.', true),
  ('59e8959d-6be5-467a-8450-3c24cce8fdf0', 'T-Bar Row', 'Horizontal Pull', 'Barbell', 'Back', ARRAY['Biceps']::text[], ARRAY['t bar row','tbar row','landmine row']::text[], 'horizontal_pull', 'pull', 'intermediate', false, false, 'weight_reps', 'lb', 'Straddle the loaded bar, hinge forward with a flat back, and row the handle to your torso, then lower under control.', 'Keep your back flat and hips hinged — drive your elbows back rather than heaving with your lower back.', true),
  ('63bef612-9476-4854-abec-af32c9a90baf', 'Pendlay Row', 'Horizontal Pull', 'Barbell', 'Back', ARRAY['Biceps']::text[], ARRAY['pendlay','pendlay rows']::text[], 'horizontal_pull', 'pull', 'advanced', false, false, 'weight_reps', 'lb', 'From a flat-back hinge with the bar on the floor, explosively row it to your lower chest, then return it to the floor each rep.', 'Reset on the floor between reps and keep your torso parallel — no rising up as you pull.', true),
  ('d75c33fa-5435-47f5-93fc-e796ad22322e', 'Inverted Row', 'Horizontal Pull', 'Bodyweight', 'Back', ARRAY['Biceps']::text[], ARRAY['bodyweight row','australian pull up','inverted rows']::text[], 'horizontal_pull', 'pull', 'beginner', true, false, 'bodyweight_reps', 'lb', 'Hang under a fixed bar with your body straight and heels on the floor, then pull your chest to the bar and lower under control.', 'Keep your body in a rigid plank line and lead with your chest, not your chin.', true),
  ('ccb0656f-0ff1-4cf7-8846-f5c65845bcd9', 'Smith Machine Row', 'Horizontal Pull', 'Smith', 'Back', ARRAY['Biceps']::text[], ARRAY['smith row','smith machine bent over row','smith machine rows']::text[], 'horizontal_pull', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'Hinge over the Smith bar with a flat back and row it to your torso along the fixed path, then lower under control.', 'Set the bar height so you can keep a flat back at the bottom of each rep.', true),
  ('2c6c689e-c443-4a2f-afc7-05aae25ff549', 'Band Row', 'Horizontal Pull', 'Band', 'Back', ARRAY['Biceps']::text[], ARRAY['resistance band row','band rows','seated band row']::text[], 'horizontal_pull', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'Anchor a band in front of you, sit or stand tall, and pull the handles to your sides by driving your elbows back, then return under control.', 'Squeeze your shoulder blades together and keep tension on the band the whole way out.', true),
  ('ba29c34a-4443-49e8-8aa3-5024311fb31f', 'Close-Grip Lat Pulldown', 'Vertical Pull', 'Cable', 'Lats', ARRAY['Biceps']::text[], ARRAY['close grip pulldown','narrow grip pulldown','close grip lat pull down']::text[], 'vertical_pull', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'With a close or V-grip handle, pull it down to your upper chest by driving your elbows down, then return under control.', 'Lead with your elbows and let your lats do the pulling, not your arms.', true),
  ('151c7147-c4d9-4826-8d23-2030b690ab6d', 'Wide-Grip Lat Pulldown', 'Vertical Pull', 'Cable', 'Lats', ARRAY['Biceps']::text[], ARRAY['wide grip pulldown','wide grip lat pull down','wide lat pulldown']::text[], 'vertical_pull', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'With a wide overhand grip, pull the bar down to your upper chest by driving your elbows down and back, then return under control.', 'Think about pulling your elbows to your ribs rather than yanking the bar with your hands.', true),
  ('a1d03bc5-97cc-40df-9412-bceeab10f668', 'Neutral-Grip Lat Pulldown', 'Vertical Pull', 'Cable', 'Lats', ARRAY['Biceps']::text[], ARRAY['neutral grip pulldown','v grip pulldown','hammer grip pulldown']::text[], 'vertical_pull', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'With a neutral (palms-facing) handle, pull it down to your upper chest by driving your elbows down, then return under control.', 'Keep a tall chest and pull to the top of your chest for the best lat stretch and squeeze.', true),
  ('0f7ac00e-5221-4c34-b5ff-e3e1543ec3ab', 'Single-Arm Lat Pulldown', 'Vertical Pull', 'Cable', 'Lats', ARRAY['Biceps']::text[], ARRAY['one arm pulldown','single arm pulldown','one arm lat pulldown']::text[], 'vertical_pull', 'pull', 'beginner', false, true, 'weight_reps', 'lb', 'Using a single handle, pull it down to your shoulder with one arm while keeping your torso stable, then extend under control.', 'Let your shoulder blade rotate with the movement and avoid leaning away to cheat.', true),
  ('2e7fab32-3500-4687-b2ff-68117ec96654', 'Assisted Pull-Up', 'Vertical Pull', 'Machine', 'Lats', ARRAY['Biceps']::text[], ARRAY['assisted pullup','machine assisted pull up','assisted pull ups']::text[], 'vertical_pull', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'Kneel or stand on the assist platform, grip the handles overhead, and pull your chin over the bar, then lower under control.', 'More assist weight makes it easier — reduce the assist over time as you get stronger toward a full pull-up.', true),
  ('bdb2c659-f671-4b48-9e2e-fc231e66f91d', 'Cable Pullover', 'Vertical Pull', 'Cable', 'Lats', ARRAY['Chest']::text[], ARRAY['straight arm pullover','cable lat pullover','rope pullover']::text[], 'isolation', 'pull', 'beginner', false, false, 'weight_reps', 'lb', 'Standing at a high pulley with nearly straight arms, pull the bar down in an arc to your thighs, then let it return overhead under control.', 'Keep your arms long with a fixed slight bend and feel your lats drive the arc, not your triceps.', true),
  ('6537df39-e313-4679-93b1-946f906667d5', 'Machine Shoulder Press', 'Vertical Push', 'Machine', 'Shoulders', ARRAY['Triceps']::text[], ARRAY['machine ohp','seated machine shoulder press','shoulder press machine']::text[], 'vertical_push', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Sit with the handles at shoulder height and press them overhead until your arms are extended, then lower under control.', 'Set the seat so the handles start at ear height and keep your back against the pad.', true),
  ('0b878c01-4ace-424c-9e85-872d265e0e2a', 'Smith Machine Shoulder Press', 'Vertical Push', 'Smith', 'Shoulders', ARRAY['Triceps']::text[], ARRAY['smith ohp','smith machine overhead press','smith shoulder press']::text[], 'vertical_push', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Seated under the Smith bar at shoulder height, press it overhead along the fixed path, then lower to shoulder level under control.', 'Position the bench so the bar path stays just in front of your face at the bottom.', true),
  ('5f9b8812-feca-4bbd-92ab-2df3a752ef39', 'Arnold Press', 'Vertical Push', 'Dumbbell', 'Shoulders', ARRAY['Triceps']::text[], ARRAY['arnold shoulder press','arnold dumbbell press','arnold presses']::text[], 'vertical_push', 'push', 'intermediate', false, false, 'weight_reps', 'lb', 'Start with dumbbells in front at shoulder height with palms facing you, then rotate your palms out as you press overhead, and reverse on the way down.', 'Make the rotation smooth and continuous so your delts stay under tension through the whole arc.', true),
  ('0a93b1f0-8548-4290-bf58-0fdb6a6db3bd', 'Cable Lateral Raise', 'Vertical Push', 'Cable', 'Shoulders', '{}'::text[], ARRAY['cable side raise','one arm cable lateral raise','cable lateral raises']::text[], 'isolation', 'push', 'beginner', false, true, 'weight_reps', 'lb', 'Standing side-on to a low pulley, raise the handle out to shoulder height with a slight elbow bend, then lower slowly.', 'The cable keeps tension at the bottom — lead with your elbow and don''t swing.', true),
  ('63712c1d-a425-4bad-a2b6-6f2aad31e4d5', 'Machine Lateral Raise', 'Vertical Push', 'Machine', 'Shoulders', '{}'::text[], ARRAY['lateral raise machine','machine side raise','machine lateral raises']::text[], 'isolation', 'push', 'beginner', false, false, 'weight_reps', 'lb', 'Sit with the pads against your outer arms and raise your elbows out to shoulder height, then lower under control.', 'Push against the pads with your elbows, not your hands, and keep the movement smooth.', true),
  ('14b53488-c28c-4cb5-ac80-e679c111c4df', 'Upright Row', 'Vertical Push', 'Barbell', 'Shoulders', ARRAY['Traps']::text[], ARRAY['barbell upright row','bb upright row','upright rows']::text[], 'vertical_pull', 'pull', 'intermediate', false, false, 'weight_reps', 'lb', 'Hold the bar in front of your thighs and pull it straight up toward your chin, leading with your elbows, then lower under control.', 'Keep the bar close to your body and stop around chest height to keep your shoulders happy.', true),
